import{_ as a,a as n,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","description":"L73–L96 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程","description":"L73–L96 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-04/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 语法总结","summary":"L73–L96 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-04/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句","link":"/life/english/new-concept/book-2/unit-04/grammar-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 现在完成时与过去时间至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-04/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结 · 动词、宾语与补足语至非真实条件句","link":"/life/english/new-concept/book-2/unit-04/grammar-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/grammar-part-02.md","filePath":"life/english/new-concept/book-2/unit-04/grammar-part-02.md"}'),i={name:"life/english/new-concept/book-2/unit-04/grammar-part-02.md"};function r(s,e,l,p,h,g){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-4-语法总结-·-时间、原因与让步从句至将来进行时与过程" tabindex="-1">第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-语法总结-·-时间、原因与让步从句至将来进行时与过程" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 语法总结 · 时间、原因与让步从句至将来进行时与过程&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><h2 id="时间、原因与让步从句" tabindex="-1">时间、原因与让步从句 <a class="header-anchor" href="#时间、原因与让步从句" aria-label="Permalink to &quot;时间、原因与让步从句 {#时间、原因与让步从句}&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：despite 后接名词或动名词，although 后接完整从句。两者都能引出不利条件，但结构不可直接替换。</p><p><strong>L79 原创例句：</strong> Despite the delay, we enjoyed the view from the plane.</p><p>尽管航班延误，我们仍欣赏了飞机上的景色。</p><p><strong>易错：</strong> despite it was late 结构不对；可用 despite the delay 或 although it was late。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-079">Lesson 79</a></p><h2 id="被动语态与信息重点" tabindex="-1">被动语态与信息重点 <a class="header-anchor" href="#被动语态与信息重点" aria-label="Permalink to &quot;被动语态与信息重点 {#被动语态与信息重点}&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was built 表一次建造事实，was later moved 表后来的移动。先后可用 later 明示，不一定每个先发生的动作都要过去完成时。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will be lowered 表计划将物资放下，不说明已经送达；have been supplied 表已经获得供应。受困者作主语时被动突出受助情况。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：are believed to 表人们的信念，不是作者证明超自然事件；are placed 描述可观察的仪式动作。两种被动承担不同的信息功能。</p><p><strong>L80 原创例句：</strong> The exhibition hall was built from glass and steel.</p><p>这座展厅是用玻璃和钢建造的。</p><p><strong>L88 原创例句：</strong> Fresh air will be supplied through a narrow pipe.</p><p>新鲜空气将通过一根细管输送进去。</p><p><strong>L96 原创例句：</strong> The lanterns are placed by the river to honour family ancestors.</p><p>人们把灯笼摆在河边，以纪念家族祖先。</p><p><strong>易错：</strong> was build 错误，build 的过去分词是 built。</p><p>through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</p><p>by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-080">Lesson 80</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-088">Lesson 88</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-096">Lesson 96</a></p><h2 id="分词修饰与逻辑主语" tabindex="-1">分词修饰与逻辑主语 <a class="header-anchor" href="#分词修饰与逻辑主语" aria-label="Permalink to &quot;分词修饰与逻辑主语 {#分词修饰与逻辑主语}&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Dressed as a worker 描述主句人物的被动装扮状态，不等于正在给别人穿衣；dressing a worker 则是主动动作，意义不同。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Hearing a strange sound 的主语应与主句司机一致；如果主句主语变成 steering wheel，就产生逻辑错误。分词开头不能掩盖谁做动作。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：fried potatoes 中 fried 表经过油炸处理的状态；frying potatoes 可指正在炸土豆的动作，不能仅看 -ing 就当形容词。</p><p><strong>L81 原创例句：</strong> Dressed as a cleaner, the prisoner walked towards the side gate.</p><p>那个囚犯扮成清洁工，向侧门走去。</p><p><strong>L86 原创例句：</strong> Hearing a strange sound, the driver slowed down immediately.</p><p>听到异常声音后，司机立即减速。</p><p><strong>L90 原创例句：</strong> The potatoes fried this morning were used for supper.</p><p>今天早上炸好的土豆被用于晚餐。</p><p><strong>易错：</strong> Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p><p>Hearing a sound, the wheel broke 让 wheel 成听声者，不符合意思。</p><p>We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-081">Lesson 81</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-086">Lesson 86</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-090">Lesson 90</a></p><h2 id="情态动词的意义与形式" tabindex="-1">情态动词的意义与形式 <a class="header-anchor" href="#情态动词的意义与形式" aria-label="Permalink to &quot;情态动词的意义与形式 {#情态动词的意义与形式}&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：might have been 是对过去的不确定推测；must have been 是强推断，仍不是亲眼确认。不能因为照片模糊就把未知当成不存在或存在的证明。</p><p><strong>L82 原创例句：</strong> The shape in the photograph might have been a large fish.</p><p>照片中的轮廓可能是一条大鱼。</p><p><strong>易错：</strong> might was 不合结构；过去推测用 might have been。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-082">Lesson 82</a></p><h2 id="将来表达与安排" tabindex="-1">将来表达与安排 <a class="header-anchor" href="#将来表达与安排" aria-label="Permalink to &quot;将来表达与安排 {#将来表达与安排}&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：will have published 表承诺在截止点前完成发布；will discuss 只表示计划讨论。报告承诺时必须保留谁承诺的，不把其当成已发生事实。</p><p><strong>L83 原创例句：</strong> The candidate promised that the council would publish a plan by June.</p><p>候选人承诺，议会会在六月前公布一项计划。</p><p><strong>易错：</strong> by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-083">Lesson 83</a></p><h2 id="将来进行时与过程" tabindex="-1">将来进行时与过程 <a class="header-anchor" href="#将来进行时与过程" aria-label="Permalink to &quot;将来进行时与过程 {#将来进行时与过程}&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be meeting 表未来某时正常安排中的会议过程，不表示谈判一定有结果；will have agreed 则是对达成协议的完成预测。</p><p><strong>L84 原创例句：</strong> At ten tomorrow, the two sides will be discussing the revised offer.</p><p>明天十点，双方将正在讨论修订后的提议。</p><p><strong>易错：</strong> discuss about the offer 多余 about；discuss 直接接宾语。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-084">Lesson 84</a></p>',55)])])}const u=a(i,[["render",r]]);export{d as __pageData,u as default};
